#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Process HWPX XML files: replace placeholders, normalize budgets,
calculate month spans, and remove layout-cache elements.
"""

import json
import os
import re
import xml.etree.ElementTree as ET

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
ET.register_namespace('hp', HP_NS)


def load_json(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def normalize_budget(value):
    """Remove commas from budget numbers while keeping the currency symbol."""
    return value.replace(',', '')


def calc_month_span(text):
    """Parse date range in text and return month span, or None."""
    # Range pattern: (YYYY-MM ~ YYYY-MM)
    m = re.search(r'\((\d{4})-(\d{2})\s*~\s*(\d{4})-(\d{2})\)', text)
    if m:
        sy, sm, ey, em = map(int, m.groups())
        return (ey - sy) * 12 + (em - sm) + 1
    # Single month pattern: (YYYY-MM)
    m = re.search(r'\((\d{4})-(\d{2})\)', text)
    if m:
        return 1
    return None


def process_files(hwpx_dir, json_path):
    data = load_json(json_path)

    # Prepare replacements
    replacements = {}
    for key, val in data.items():
        if key == '예산':
            replacements[key] = normalize_budget(val)
        else:
            replacements[key] = val

    # Gather all XML files
    xml_files = []
    for root_dir, dirs, files in os.walk(hwpx_dir):
        for f in files:
            if f.endswith('.xml'):
                xml_files.append(os.path.join(root_dir, f))

    for xml_path in xml_files:
        tree = ET.parse(xml_path)
        root = tree.getroot()

        # Build a parent map so we can remove elements easily
        parent_map = {c: p for p in root.iter() for c in p}

        modified_doc = False

        for para in root.iter(f'{{{HP_NS}}}p'):
            # Gather all <hp:t> elements inside this paragraph
            t_elems = list(para.iter(f'{{{HP_NS}}}t'))
            if not t_elems:
                continue

            original_text = ''.join(t.text or '' for t in t_elems)
            new_text = original_text

            # 1) Replace placeholders
            for key, val in replacements.items():
                pattern = f'{{{{{key}}}}}'
                new_text = new_text.replace(pattern, val)

            # 2) Append month span for phase lines
            if '단계' in new_text:
                span = calc_month_span(new_text)
                if span is not None:
                    suffix = f'({span}개월)'
                    if suffix not in new_text:
                        new_text = new_text + ' ' + suffix

            if new_text != original_text:
                modified_doc = True

                # Reconstruct text nodes: put all text in the first <hp:t>,
                # remove the rest. This naturally fixes fragmentation.
                t_elems[0].text = new_text
                for t in t_elems[1:]:
                    parent = parent_map.get(t)
                    if parent is not None:
                        parent.remove(t)
                        del parent_map[t]

                # 3) Remove layout-cache elements from modified paragraph
                for cache_tag in ['linesegarray', 'lineseg']:
                    for cache_elem in list(para.iter(f'{{{HP_NS}}}{cache_tag}')):
                        parent = parent_map.get(cache_elem)
                        if parent is not None:
                            parent.remove(cache_elem)
                            del parent_map[cache_elem]

        if modified_doc:
            tree.write(xml_path, encoding='utf-8', xml_declaration=True)
            # Normalize XML declaration to match original style
            with open(xml_path, 'r', encoding='utf-8') as f:
                content = f.read()
            content = content.replace(
                "<?xml version='1.0' encoding='UTF-8'?>",
                "<?xml version='1.0' encoding='utf-8'?>"
            )
            with open(xml_path, 'w', encoding='utf-8') as f:
                f.write(content)


if __name__ == '__main__':
    process_files('/root/hwpx_work', '/root/project_proposal.json')

